/**
 * A git `post-receive` hook that triggers a KiCI run on every push to a local
 * (`file://`) source; a thin wrapper around `kici-admin source trigger-local`.
 */
import { writeFileSync, chmodSync, existsSync } from 'node:fs';
import path from 'node:path';

/** Each pushed ref dispatches a run whose changed files are the pushed commits (`<old>..<new>`). */
export function renderPostReceiveHook(opts: { sourceId: string; baseUrl: string }): string {
  return `#!/usr/bin/env bash
# KiCI local-source post-receive hook (generated by 'kici-admin source install-hook').
# Triggers a run for each pushed branch ref.
set -euo pipefail
while read -r _old _new ref; do
  kici-admin source trigger-local ${opts.sourceId} --ref "$ref" --before "$_old" --sha "$_new" --base-url ${opts.baseUrl}
done
`;
}

/** Write the hook as executable `.git/hooks/post-receive`; throws when there is no `.git/hooks`. */
export function installPostReceiveHook(repoPath: string, script: string): string {
  const hooksDir = path.join(repoPath, '.git', 'hooks');
  if (!existsSync(hooksDir)) {
    throw new Error(`Not a git repo (no .git/hooks): ${repoPath}`);
  }
  const hookPath = path.join(hooksDir, 'post-receive');
  writeFileSync(hookPath, script, { mode: 0o755 });
  chmodSync(hookPath, 0o755);
  return hookPath;
}
